    "border-dashed",
    "border-chrome-border-strong",
    "bg-chrome-bg",
    "flex",
    "[flex-direction:column]",
    "[align-items:center]",
    "[justify-content:center]",
    "gap-space-2",
    "my-space-6",
    "mx-0",
    "[max-width:none]",
    /* `.ph:has(img)` — THE FRAME STEPS ASIDE. Once a real <img> is inside, every one of the
       placeholder's own decisions is wrong — the dashed border is chrome around content,
       the tinted background sits behind an opaque picture, and the 16:9 ratio would crop or
       letterbox artwork that has a ratio of its own. So all three are undone by the content
       rather than by a class somebody has to remember to add, which is the whole reason
       this is a `contains` and not a variant. */
